            dd[2] = 0.0;
            dd[3] = 0.0;
            dd[4] = 0.0;
            dd[5] = vpH * _rcp1;
            dd[6] = 0.0;
            dd[7] = 0.0;
            dd[8] = 0.0;
            dd[9] = 0.0;
            dd[10] = 1.0;
            dd[11] = 0.0;
            dd[12] = java.lang.Math.fma(-2.0, centerX - vpX, vpW) * _rcp0;
            dd[13] = java.lang.Math.fma(-2.0, centerY - vpY, vpH) * _rcp1;
