            double _rcp1 = 1.0 / deltaY;
            dd[0] = vpW * _rcp0;
            dd[1] = 0.0;
            dd[2] = 0.0;
            dd[3] = 0.0;
            dd[4] = 0.0;
            dd[5] = vpH * _rcp1;
            dd[6] = 0.0;
            dd[7] = 0.0;
            dd[8] = 0.0;
            dd[9] = 0.0;
            dd[10] = 1.0;
            dd[11] = 0.0;
            dd[12] = ((-2.0) * (centerX - vpX) + (vpW)) * _rcp0;
            dd[13] = ((-2.0) * (centerY - vpY) + (vpH)) * _rcp1;
            dd[14] = 0.0;
            dd[15] = 1.0;
            this.properties = Joml.BIT_AFFINE;
