        if ((p & Joml.BIT_ORTHOGONAL) == Joml.BIT_ORTHOGONAL) return (Math.useFma() ? obliqueCabinet_orthogonal_fma_narrow(angle, dest) : obliqueCabinet_orthogonal_mulAdd_narrow(angle, dest));
